// === Tab: Barb ===
class Barb {
	constructor(pos, vel, ang, seed, swerve, id) {
		this.pos = pos;
		this.lpos = createVector(pos.x, pos.y);
		this.vel = vel;
		this.ang = ang;
		this.seed = seed;
		this.length = 1;
		this.age = -PI / 15;
		this.alive = true;
		this.ra = random(60, 90);
		this.ba = random(40, 60);
		this.ga = (55 + 80 * noise(pos.x / 5)) * 1.25
		this.col = color(this.ra, this.ga, this.ba);
		this.swerve = swerve;
		this.id = id;
		this.erode = map(id, 700, 0, 1, 0.98, true);
	}
	move() {
		this.seed += 0.001;
		this.swerve *= this.erode;
		if (this.id > 700 && this.age > -PI / 240) this.swerve *= map(this.id, 1000, 700, 0.998, 0.975);
		this.ang -= (0.49 - noise(this.seed)) / this.swerve;
		this.vel.x = cos(this.ang);
		this.vel.y = 2 * sin(this.ang);
		this.pos.add(this.vel);
		this.length = abs(1.5 * cos(this.age));
		this.age += 0.01;
		if (this.age >= HALF_PI) this.alive = false;
		let d = dist(this.pos.x, this.pos.y / 1.2, this.id / 3.2, 0);
		let ang = atan2(this.pos.y / 1.2, (this.pos.x - this.id / 3.2));
		if (d < (550 / 32) * (1 - cos(ang))) {
			this.col.setAlpha(200);
			this.col.setRed(0);
			this.col.setGreen(0);
			this.col.setBlue(0);
		} else if (d < 550 / 14) {
			this.col.setRed(0);
			this.col.setBlue(240);
			this.col.setGreen(this.ga);
			this.col.setAlpha(20);
		} else if (d < 550 / 11) {
			this.col.setRed(this.ra);
			this.col.setGreen(this.ga * 1.5)
			this.col.setBlue(this.ba * 2.5);
			this.col.setAlpha(160);
		} else if (d < 550 / 9) {
			this.col.setRed(180);
			this.col.setGreen(this.ga);
			this.col.setBlue(this.ba);
			this.col.setAlpha(120);
		} else {
			this.col.setRed(this.ra);
			this.col.setGreen(this.ga);
			this.col.setBlue(this.ba);
			this.col.setAlpha(180);
		}
	}
	show() {
		stroke(this.col);
		strokeWeight(this.length);
		line(this.pos.x, this.pos.y, this.lpos.x, this.lpos.y);
		push();
		strokeWeight(0.2);
		translate(this.pos.x, this.pos.y);
		rotate(this.ang);
		line(0, 0, 15 * this.length, 0); //barbule!
		pop();
		this.lpos.x = this.pos.x
		this.lpos.y = this.pos.y
	}
}

