// They look like they're soft?

let barbs = [];
let i = 1000;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
}

function draw() {
	if (i > 0) {
		let x = map(i, 1000, 0, 600 / 1.5, -600);
		let pos = createVector(x, 0);
		let a = map(i, 0, 1000, -PI, PI);
		let ang = sin(a) / 1.5;
		if (i > 200 && i < 800 && abs(ang) < PI / 18) ang = Math.sign(ang) * PI / 18;
		if (i % 2 == 0) ang *= -1;
		let vel = createVector(0, 0);
		let seed = 1800 + x;
		let straggle = map(i, 0, 1000, 10, 150);
		barbs.push(new Barb(pos, vel, ang, seed, straggle, i));
		if(i<700) i-=floor(random(3))
		i--;
	}
	translate(width / 2, height / 2);
	scale(height / 700);
	rotate(map(frameCount, 0, 1000, -PI / 12, -PI / 6));
	barbs = barbs.filter(b => b.alive);
	for (let b of barbs) {
		b.move();
		b.show();
	}
}

